/* Casa in Rete v4 · modello «co-housing fra privati con infermiere di riferimento».
   Tutti i dati sono inventati per la prova: case, persone, canoni, infermieri, valutazioni, parenti. */
const OGGI = new Date(2026, 10, 25); // 25 novembre 2026, data fissa della prova

/* Regole del modello: proposte da validare (vedi nuovo-modello/APPROCCIO.md). */
const REGOLE = {
  maxAbitanti: 4,             // ospitanti compresi. L.R. Lazio 16/2026: coabitazione fino a 6 ospiti (art. 8), strutture familiari fino a 8 con autorizzazione (art. 4)
  barthelMin: 91,             // si entra solo autonomi o con dipendenza lieve: la casa resta una casa (TAR Lazio 1286/2022)
  commissione: 0,             // versione per la gara (non commerciale): nessuna commissione; il programma lo gestisce un Comune o un ente del Terzo settore
  euroGiornoCasa: 8,          // all'infermiere 8 € per ogni giorno FERIALE e ogni casa seguita (F59, F61): domeniche e festivi esclusi
  maxCaseInfermiere: 10,      // ogni infermiere segue al massimo 10 case (F59)
  aiutoGiorniMax: 60,         // l'aiuto condiviso dura al massimo 60 giorni, poi nuova valutazione
  aiutoOreMax: 4,             // ore al giorno al massimo: oltre, la casa si avvicina a una struttura
  tariffe: { oss: 23.69, collaboratrice: 12, badante: 12 }, // badante: valore di prova // euro all'ora. OSS: costo del lavoro C2, coop. sociali 2026 (F21). Collaboratrice: valore di prova
  controlloMesi: 6,           // controllo strutturato ogni 6 mesi, prima se arrivano segnali
  caricoPerPersona: 2,        // punti medi sostenibili per persona seguita (come nel mockup v3)
  depositoMesi: 2,            // deposito cauzionale: due mesi di affitto (valore di prova)
  giornoScadenza: 5,          // affitto e quota si pagano direttamente entro il 5 del mese
  interventiInclusi: 6,       // interventi piccoli garantiti al mese per persona (F58, F59)
  prezzoIntervento: 12,       // i 6 interventi del mese sono GIÀ PAGATI nella quota dell'infermiere: 6 × 12 = 72 € a persona (F61)
  tariffaIntervento: 20       // dalla 7ª prestazione del mese, e per ogni intervento in un giorno festivo (salvo terapia iniziata in un feriale), 20 € da pagare all'infermiere il mese dopo (F61)
};

